"""Utility functions: logging, seeding, path management, I/O."""

import json
import logging
import random
from pathlib import Path
from typing import Any

import numpy as np
import torch


def setup_logging(level: str = "INFO") -> logging.Logger:
    logging.basicConfig(
        format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
        level=getattr(logging, level.upper()),
    )
    return logging.getLogger("pgpf")


logger = setup_logging()


def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)


def ensure_dir(path: str | Path) -> Path:
    p = Path(path)
    p.mkdir(parents=True, exist_ok=True)
    return p


def save_jsonl(data: list[dict], path: str | Path) -> None:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        for item in data:
            f.write(json.dumps(item, ensure_ascii=False) + "\n")


def load_jsonl(path: str | Path) -> list[dict]:
    with open(path, "r", encoding="utf-8") as f:
        return [json.loads(line) for line in f if line.strip()]


def save_json(data: Any, path: str | Path) -> None:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)


def load_json(path: str | Path) -> Any:
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def get_device() -> torch.device:
    if torch.cuda.is_available():
        return torch.device("cuda")
    return torch.device("cpu")

"""Property scoring: lexical conformity, semantic novelty, quality (PPL), confidence.

Each scorer operates on text samples and returns float scores.
Batch interface aggregates all four properties into a list of score dicts.
GPU-intensive operations (embedding, perplexity) are batched for efficiency.
"""

import random
from typing import Optional

import numpy as np
import torch
from torch.nn import functional as F


def _lazy_import_sacrebleu():
    import sacrebleu
    return sacrebleu


class PropertyScorer:
    """Compute all four properties for a batch of samples."""

    def __init__(
        self,
        embedding_model_name: str = "dunzhang/stella_en_1.5B_v5",
        corpus_k: int = 50,
        device: Optional[str] = None,
    ):
        self.embedding_model_name = embedding_model_name
        self.corpus_k = corpus_k
        self.device = device or ("cuda" if torch.cuda.is_available() else "cpu")

        self._embed_model = None
        self._corpus_centroid: Optional[np.ndarray] = None
        self._corpus_texts: Optional[list[str]] = None

    def _get_embed_model(self):
        if self._embed_model is None:
            from sentence_transformers import SentenceTransformer
            self._embed_model = SentenceTransformer(self.embedding_model_name, device=self.device)
        return self._embed_model

    def set_reference_corpus(self, texts: list[str]) -> None:
        """Set gen-0 corpus for semantic novelty (centroid) and lexical conformity."""
        self._corpus_texts = texts
        model = self._get_embed_model()
        embeddings = model.encode(texts, batch_size=64, show_progress_bar=True, convert_to_numpy=True)
        self._corpus_centroid = embeddings.mean(axis=0)

    def lexical_conformity(self, sample: str, corpus_subset: Optional[list[str]] = None, k: int = 50) -> float:
        """Average BLEU-4 of sample against k random reference samples."""
        sacrebleu = _lazy_import_sacrebleu()
        if corpus_subset is None:
            if self._corpus_texts is None:
                raise ValueError("Call set_reference_corpus() first or pass corpus_subset")
            corpus_subset = self._corpus_texts

        refs = random.sample(corpus_subset, min(k, len(corpus_subset)))
        bleu_scores = []
        for ref in refs:
            bleu = sacrebleu.sentence_bleu(sample, [ref])
            bleu_scores.append(bleu.score / 100.0)
        return float(np.mean(bleu_scores))

    def semantic_novelty(self, sample_embedding: np.ndarray, corpus_centroid: Optional[np.ndarray] = None) -> float:
        """Cosine distance between sample embedding and corpus centroid."""
        if corpus_centroid is None:
            if self._corpus_centroid is None:
                raise ValueError("Call set_reference_corpus() first or pass corpus_centroid")
            corpus_centroid = self._corpus_centroid

        cos_sim = np.dot(sample_embedding, corpus_centroid) / (
            np.linalg.norm(sample_embedding) * np.linalg.norm(corpus_centroid) + 1e-8
        )
        return float(1.0 - cos_sim)

    @staticmethod
    @torch.no_grad()
    def quality_score(sample: str, model, tokenizer, max_length: int = 2048) -> float:
        """Perplexity of sample under the given model (lower = higher quality)."""
        encodings = tokenizer(sample, return_tensors="pt", truncation=True, max_length=max_length)
        input_ids = encodings.input_ids.to(model.device)
        outputs = model(input_ids, labels=input_ids)
        return float(torch.exp(outputs.loss).item())

    @staticmethod
    @torch.no_grad()
    def confidence_score(sample: str, model, tokenizer, max_length: int = 2048) -> float:
        """Average token-level log-probability under the generating model."""
        encodings = tokenizer(sample, return_tensors="pt", truncation=True, max_length=max_length)
        input_ids = encodings.input_ids.to(model.device)
        outputs = model(input_ids)
        logits = outputs.logits[:, :-1, :]
        targets = input_ids[:, 1:]
        log_probs = F.log_softmax(logits, dim=-1)
        token_log_probs = log_probs.gather(2, targets.unsqueeze(-1)).squeeze(-1)
        return float(token_log_probs.mean().item())

    def embed_texts(self, texts: list[str], batch_size: int = 64) -> np.ndarray:
        model = self._get_embed_model()
        return model.encode(texts, batch_size=batch_size, show_progress_bar=True, convert_to_numpy=True)

    def score_batch(
        self,
        samples: list[str],
        model=None,
        tokenizer=None,
        base_model=None,
        base_tokenizer=None,
        compute_lexical: bool = True,
        compute_semantic: bool = True,
        compute_quality: bool = True,
        compute_confidence: bool = True,
    ) -> list[dict[str, float]]:
        """Score a batch of samples on all four properties.

        Args:
            samples: list of text samples
            model: the generating model (for confidence)
            tokenizer: tokenizer for the generating model
            base_model: the gen-0 base model (for quality/PPL)
            base_tokenizer: tokenizer for the base model
            compute_*: toggle individual properties

        Returns:
            list of {"lexical_conformity", "semantic_novelty", "quality", "confidence"} dicts
        """
        n = len(samples)
        results: list[dict[str, float]] = [{}  for _ in range(n)]

        if compute_semantic:
            embeddings = self.embed_texts(samples)
            for i in range(n):
                results[i]["semantic_novelty"] = self.semantic_novelty(embeddings[i])

        if compute_lexical:
            for i, s in enumerate(samples):
                results[i]["lexical_conformity"] = self.lexical_conformity(s)

        if compute_quality and base_model is not None and base_tokenizer is not None:
            for i, s in enumerate(samples):
                results[i]["quality"] = self.quality_score(s, base_model, base_tokenizer)

        if compute_confidence and model is not None and tokenizer is not None:
            for i, s in enumerate(samples):
                results[i]["confidence"] = self.confidence_score(s, model, tokenizer)

        return results

"""Filter strategies for selecting synthetic samples each generation.

All filters implement the same interface: filter(samples, scores) -> filtered_samples.
retention_rate controls what fraction of samples to keep (critical control variable).
"""

import random
from abc import ABC, abstractmethod
from typing import Optional

import numpy as np


class BaseFilter(ABC):
    def __init__(self, retention_rate: float = 0.5):
        assert 0.0 < retention_rate <= 1.0
        self.retention_rate = retention_rate

    @abstractmethod
    def filter(
        self, samples: list[dict], scores: list[dict[str, float]]
    ) -> list[dict]:
        ...

    def _target_count(self, n: int) -> int:
        return max(1, int(n * self.retention_rate))


class NoFilter(BaseFilter):
    def __init__(self, retention_rate: float = 1.0):
        super().__init__(retention_rate=1.0)

    def filter(self, samples: list[dict], scores: list[dict[str, float]]) -> list[dict]:
        return list(samples)


class RandomFilter(BaseFilter):
    def filter(self, samples: list[dict], scores: list[dict[str, float]]) -> list[dict]:
        k = self._target_count(len(samples))
        return random.sample(samples, k)


class ConfidenceFilter(BaseFilter):
    """Keep top-k samples ranked by confidence (average log-prob)."""

    def filter(self, samples: list[dict], scores: list[dict[str, float]]) -> list[dict]:
        k = self._target_count(len(samples))
        paired = list(zip(samples, scores))
        paired.sort(key=lambda x: x[1].get("confidence", float("-inf")), reverse=True)
        return [s for s, _ in paired[:k]]


class PGPFStaticFilter(BaseFilter):
    """Property-guided filtering: keep samples passing ALL three property thresholds.

    Thresholds are percentile-based, computed from the score distribution.
    If fewer samples pass than retention_rate allows, return all passing samples.
    If more pass, randomly subsample to retention_rate.

    For lexical_conformity and quality (PPL): lower is better → keep below threshold.
    For semantic_novelty: higher means more novel → keep above threshold.
    """

    def __init__(
        self,
        retention_rate: float = 0.5,
        lexical_conformity_percentile: float = 50.0,
        semantic_novelty_percentile: float = 50.0,
        quality_percentile: float = 50.0,
    ):
        super().__init__(retention_rate)
        self.lc_pct = lexical_conformity_percentile
        self.sn_pct = semantic_novelty_percentile
        self.q_pct = quality_percentile

    def filter(self, samples: list[dict], scores: list[dict[str, float]]) -> list[dict]:
        n = len(samples)
        k = self._target_count(n)

        lc_vals = np.array([s.get("lexical_conformity", 0.0) for s in scores])
        sn_vals = np.array([s.get("semantic_novelty", 0.0) for s in scores])
        q_vals = np.array([s.get("quality", float("inf")) for s in scores])

        # Lexical conformity: moderate is good; filter out extremes (top percentile = too conforming)
        lc_thresh = np.percentile(lc_vals, self.lc_pct)
        # Semantic novelty: keep samples above percentile threshold (more novel)
        sn_thresh = np.percentile(sn_vals, self.sn_pct)
        # Quality (PPL): lower is better; keep below threshold
        q_thresh = np.percentile(q_vals, self.q_pct)

        passing_indices = []
        for i in range(n):
            if lc_vals[i] <= lc_thresh and sn_vals[i] >= sn_thresh and q_vals[i] <= q_thresh:
                passing_indices.append(i)

        if len(passing_indices) > k:
            passing_indices = random.sample(passing_indices, k)

        return [samples[i] for i in passing_indices]


class LexicalOnlyFilter(BaseFilter):
    """Keep samples with lexical conformity below the percentile threshold."""

    def __init__(self, retention_rate: float = 0.5, threshold_percentile: float = 50.0):
        super().__init__(retention_rate)
        self.threshold_percentile = threshold_percentile

    def filter(self, samples: list[dict], scores: list[dict[str, float]]) -> list[dict]:
        n = len(samples)
        k = self._target_count(n)

        lc_vals = np.array([s.get("lexical_conformity", 0.0) for s in scores])
        thresh = np.percentile(lc_vals, self.threshold_percentile)

        passing = [i for i in range(n) if lc_vals[i] <= thresh]
        if len(passing) > k:
            passing = random.sample(passing, k)

        return [samples[i] for i in passing]


FILTER_REGISTRY: dict[str, type[BaseFilter]] = {
    "no_filter": NoFilter,
    "random": RandomFilter,
    "confidence": ConfidenceFilter,
    "pgpf_static": PGPFStaticFilter,
    "lexical_only": LexicalOnlyFilter,
}


def build_filter(config) -> BaseFilter:
    """Instantiate a filter from a PGPFConfig."""
    method = config.filter_method
    cls = FILTER_REGISTRY[method]
    if method == "pgpf_static":
        return cls(
            retention_rate=config.retention_rate,
            lexical_conformity_percentile=config.lexical_conformity_percentile,
            semantic_novelty_percentile=config.semantic_novelty_percentile,
            quality_percentile=config.quality_percentile,
        )
    if method == "lexical_only":
        return cls(
            retention_rate=config.retention_rate,
            threshold_percentile=config.lexical_conformity_percentile,
        )
    if method == "no_filter":
        return cls()
    return cls(retention_rate=config.retention_rate)

"""Data preparation: download OpenHermes-2.5, subsample, format for SFT, save as JSONL.

Output format (ChatML):
  {"messages": [{"role": "system", "content": "..."}, {"role": "user", "content": "..."}, {"role": "assistant", "content": "..."}]}
"""

import argparse
import random
from pathlib import Path
from typing import Optional

from pgpf.utils import save_jsonl, load_jsonl, ensure_dir, set_seed, logger


def _format_conversation(example: dict) -> Optional[dict]:
    """Convert an OpenHermes-2.5 example to ChatML messages format."""
    conversations = example.get("conversations", [])
    if not conversations:
        return None

    messages = []
    role_map = {"system": "system", "human": "user", "gpt": "assistant"}

    for turn in conversations:
        role = role_map.get(turn.get("from", ""), None)
        if role is None:
            continue
        messages.append({"role": role, "content": turn["value"]})

    if not any(m["role"] == "assistant" for m in messages):
        return None

    return {"messages": messages}


def prepare_dataset(
    output_dir: str = "data",
    subset_size: int = 10000,
    train_size: int = 8000,
    val_size: int = 1000,
    test_size: int = 1000,
    seed: int = 42,
) -> dict[str, Path]:
    """Download OpenHermes-2.5, subsample, split, and save as JSONL."""
    from datasets import load_dataset

    set_seed(seed)
    out = ensure_dir(output_dir)

    logger.info("Loading OpenHermes-2.5 from HuggingFace...")
    ds = load_dataset("teknium/OpenHermes-2.5", split="train")

    logger.info(f"Total examples: {len(ds)}, sampling {subset_size}")
    indices = random.sample(range(len(ds)), min(subset_size, len(ds)))
    subset = ds.select(indices)

    formatted = []
    for example in subset:
        result = _format_conversation(example)
        if result is not None:
            formatted.append(result)

    random.shuffle(formatted)
    assert len(formatted) >= train_size + val_size + test_size, (
        f"Not enough valid examples ({len(formatted)}) for requested splits"
    )

    splits = {
        "train": formatted[:train_size],
        "val": formatted[train_size : train_size + val_size],
        "test": formatted[train_size + val_size : train_size + val_size + test_size],
    }

    paths = {}
    for name, data in splits.items():
        path = out / f"{name}.jsonl"
        save_jsonl(data, path)
        paths[name] = path
        logger.info(f"Saved {name}: {len(data)} examples → {path}")

    return paths


def load_dataset_splits(data_dir: str = "data") -> dict[str, list[dict]]:
    """Load pre-saved train/val/test JSONL files."""
    data_dir = Path(data_dir)
    splits = {}
    for name in ["train", "val", "test"]:
        path = data_dir / f"{name}.jsonl"
        if path.exists():
            splits[name] = load_jsonl(path)
            logger.info(f"Loaded {name}: {len(splits[name])} examples from {path}")
        else:
            logger.warning(f"{path} not found, skipping {name} split")
    return splits


def extract_assistant_texts(samples: list[dict]) -> list[str]:
    """Extract assistant turn text from ChatML formatted samples."""
    texts = []
    for sample in samples:
        for msg in sample.get("messages", []):
            if msg["role"] == "assistant":
                texts.append(msg["content"])
    return texts


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Prepare OpenHermes-2.5 subset for PGPF")
    parser.add_argument("--output_dir", type=str, default="data")
    parser.add_argument("--subset_size", type=int, default=10000)
    parser.add_argument("--seed", type=int, default=42)
    args = parser.parse_args()
    prepare_dataset(output_dir=args.output_dir, subset_size=args.subset_size, seed=args.seed)

